@Override
public boolean equals(final Object obj) {
    if (this == obj) {
        return true;
    }
    if (!(obj instanceof Option)) {
        return false;
    }
    final Option other = (Option) obj;
    return Objects.equals(longOption, other.longOption) && Objects.equals(option, other.option);
}
